// Explicit Team authoring creates a module draft. It never guesses semantics from call names.
const teamDrafts=new Map();let teamAuthor=null,teamAuthorSchema=null,teamAuthorRequest=0;
function initialTeamDefinition(){return {kind:'team',name:'My team',entry:'worker',roles:[{id:'worker',parent:null,capabilities:[],agent:{kind:'agent',name:'worker',config:{}}}]};}
function renameTeamRole(definition,role,next){const previous=role.id,unique=definition.roles.filter(x=>x.id===previous).length===1;role.id=next;if(unique){if(definition.entry===previous)definition.entry=next;for(const other of definition.roles)if(other!==role&&other.parent===previous)other.parent=next;}}
function teamRolePath(definition,role){const path=[],seen=new Set();let current=role;while(current&&path.length<64&&!seen.has(current)){seen.add(current);path.unshift(current.id);if(current.parent===null)return {path,complete:true};current=definition.roles.find(x=>x.id===current.parent);}return {path,complete:false};}
function newTeamRole(definition){let id='role',i=2;while(definition.roles.some(x=>x.id===id))id='role'+i++;return {id,parent:null,capabilities:[],agent:{kind:'agent',name:id,config:{}}};}
function teamDraftChanged(d){d.serial++;d.dirty=true;d.preview=null;const status=document.getElementById('teamAuthorStatus');if(status)status.textContent='本页团队草稿已修改；尚未验证。';const source=document.getElementById('teamAuthorSource');if(source)window.ChaosCode.update(source,'',{language:'chaos',label:'团队源码',analyze:false});const insert=document.getElementById('teamAuthorImport');if(insert)insert.disabled=true;}
function removeTeamConfig(d,role,key){delete role.agent.config[key];if(d.buffers.get(role)?.key===key)d.buffers.delete(role);}
function teamField(parent,label,value,change,multiline=false){const box=element('div','team-author-field'),input=element(multiline?'textarea':'input');box.append(element('label','',label));input.value=value;input.setAttribute('aria-label',label);if(multiline)input.rows=3;input.oninput=()=>change(input.value,input);box.append(input);parent.append(box);return input;}
function teamSelect(parent,label,value,options,change){const box=element('div','team-author-field'),select=element('select');box.append(element('label','',label));select.setAttribute('aria-label',label);const rows=options.slice();if(!rows.some(([key])=>key===value))rows.push([value,'未解析：'+value]);for(const [key,title]of rows){const option=element('option','',title);option.value=key;option.selected=key===value;select.append(option);}select.onchange=()=>change(select.value);box.append(select);parent.append(box);return select;}
function teamChecks(parent,label,selected,options,change,callableCatalog=null){const details=element('details','team-author-checks');details.append(element('summary','',label+' · '+selected.length+' 项'));for(const name of [...new Set([...selected,...options])].sort()){const row=element('label'),input=element('input');input.type='checkbox';input.checked=selected.includes(name);input.setAttribute('aria-label',label+' '+name);const allowed=!callableCatalog||callableCapability(name,callableCatalog);input.onchange=()=>{if(!allowed&&input.checked){input.checked=false;return;}const next=input.checked?[...new Set([...selected,name])]:selected.filter(x=>x!==name);selected=next;change(next);details.querySelector('summary').textContent=label+' · '+next.length+' 项';};row.append(input,element('span','',name+(allowed?'':' · '+capabilityWarning(name,callableCatalog))));details.append(row);}parent.append(details);}
async function openTeamAuthor(){
 if(!project)return;const projectId=project.id,request=++teamAuthorRequest;
 if(!teamAuthorSchema){const [schema,capabilities]=await Promise.all([api('/api/v1/teams/schema'),api('/api/capabilities')]);if(request!==teamAuthorRequest||project?.id!==projectId)return;teamAuthorSchema={schema,capabilities};}
 let d=teamDrafts.get(projectId);if(!d){d={projectId,definition:initialTeamDefinition(),serial:0,dirty:false,preview:null,buffers:new Map(),name:'saved_team'};teamDrafts.set(projectId,d);}teamAuthor=d;
 let dialog=document.getElementById('teamAuthorDialog');if(!dialog){dialog=element('dialog','team-author-dialog');dialog.id='teamAuthorDialog';dialog.setAttribute('aria-label','团队定义编辑器');document.body.append(dialog);}renderTeamAuthor();dialog.showModal();
}
function renderTeamAuthor(){
 const d=teamAuthor,definition=d.definition,dialog=document.getElementById('teamAuthorDialog');dialog.replaceChildren();dialog.append(element('h2','','编写团队'),element('p','syntax-note','独立的本地定义草稿；关闭可保留，刷新页面会丢失。验证后生成普通语言模块，不修改已有动态表达式。关系限定能力范围，不会自动调用上级或授予项目权限。此表单编写默认 Agent；本轮函数实现请在源码中用 team_bind 显式绑定，JSON 不恢复闭包。'));
 const status=element('p','syntax-note',d.dirty?'本页团队草稿已修改；尚未验证。':'填写成员及能力，再验证生成源码。');status.id='teamAuthorStatus';status.setAttribute('role','status');dialog.append(status);
 const layout=element('div','team-author-layout'),fields=element('div','team-author-fields'),side=element('aside','team-author-relations');layout.append(fields,side);dialog.append(layout);
 const renderRelations=()=>{side.replaceChildren(element('h3','','角色关系预览'));for(const role of definition.roles){const info=teamRolePath(definition,role),row=element('div','team-relation');row.append(element('strong','',info.path.join(' → ')),element('small','',(info.complete?'':'关系未闭合 · ')+role.capabilities.length+' 项能力 · 默认 Agent '+role.agent.name));side.append(row);}side.append(element('p','syntax-note','子成员的能力必须是父成员子集；Agent 请求工具必须在成员能力内。共享语言校验器做最终检查。'));};
 const changed=()=>{teamDraftChanged(d);renderRelations();};
 teamField(fields,'团队名称',definition.name,value=>{definition.name=value;changed();});
 teamSelect(fields,'入口角色',definition.entry,definition.roles.map(r=>[r.id,r.id]),value=>{definition.entry=value;changed();});
 const roleSchema=teamAuthorSchema.schema.properties.roles.items.properties,configSchema=roleSchema.agent.properties.config.properties,tools=Object.keys(teamAuthorSchema.capabilities.tools||{});
 definition.roles.forEach((role,index)=>{const card=element('section','team-role-card');card.append(element('h3','','成员 '+(index+1)));fields.append(card);const id=teamField(card,'成员 '+(index+1)+' 标识',role.id,value=>{renameTeamRole(definition,role,value);changed();});id.onchange=()=>renderTeamAuthor();
 teamSelect(card,'成员 '+(index+1)+' 父成员',role.parent??'',[['','无父成员'],...definition.roles.filter(x=>x!==role).map(x=>[x.id,x.id])],value=>{role.parent=value||null;changed();});
 teamField(card,'成员 '+(index+1)+' Agent 名称',role.agent.name,value=>{role.agent.name=value;changed();});
 teamChecks(card,'成员 '+(index+1)+' 能力范围',role.capabilities,tools,values=>{role.capabilities=values;changed();});
 for(const [key,spec]of Object.entries(configSchema)){if(!Object.hasOwn(role.agent.config,key))continue;const box=element('div','team-config-field'),label='成员 '+(index+1)+' '+(spec.title||key);card.append(box);const value=role.agent.config[key];
  if(spec.type==='array')teamChecks(box,label,value,callableChoices(teamAuthorSchema.capabilities.tools||{},value),values=>{role.agent.config[key]=values;changed();},teamAuthorSchema.capabilities.tools||{});
  else if(spec.enum)teamSelect(box,label,value,spec.enum.map(x=>[x,x]),value=>{role.agent.config[key]=value;changed();});
  else {const input=teamField(box,label,value,(value,input)=>{if(spec.type==='integer'){const numeric=/^-?\d+$/.test(value)?Number(value):NaN;if(!Number.isSafeInteger(numeric)){d.buffers.set(role,{key,value});input.setCustomValidity('请输入整数。');}else{d.buffers.delete(role);input.setCustomValidity('');role.agent.config[key]=numeric;}}else role.agent.config[key]=value;changed();},key==='prompt'||key==='policy');const pending=d.buffers.get(role);if(pending?.key===key){input.value=pending.value;input.setCustomValidity('请输入整数。');}}
  const remove=element('button','','移除 '+(spec.title||key));remove.onclick=()=>{removeTeamConfig(d,role,key);changed();renderTeamAuthor();};box.append(remove);
 }
 const missing=Object.keys(configSchema).filter(key=>!Object.hasOwn(role.agent.config,key));if(missing.length){const add=element('div','syntax-list-head'),select=element('select');select.setAttribute('aria-label','成员 '+(index+1)+' 新增配置');for(const key of missing){const option=element('option','',configSchema[key].title||key);option.value=key;select.append(option);}const button=element('button','','添加配置字段');button.onclick=()=>{const key=select.value,spec=configSchema[key];role.agent.config[key]=spec.enum?.[0]??(spec.type==='array'?[]:spec.type==='integer'?spec.minimum??0:'');changed();renderTeamAuthor();};add.append(select,button);card.append(add);}
 const remove=element('button','','删除成员 '+(index+1));remove.onclick=()=>{definition.roles.splice(definition.roles.indexOf(role),1);d.buffers.delete(role);changed();renderTeamAuthor();};card.append(remove);
 });
 const add=element('button','','添加成员');add.onclick=()=>{definition.roles.push(newTeamRole(definition));changed();renderTeamAuthor();};fields.append(add);renderRelations();
 const advanced=element('details','team-definition-json');advanced.append(element('summary','','从明确的定义 JSON 载入'));const raw=element('textarea');raw.rows=6;raw.setAttribute('aria-label','团队定义 JSON');raw.value=d.raw||'';raw.oninput=()=>{d.raw=raw.value;teamDraftChanged(d);};advanced.append(raw);const load=element('button','','校验并载入此 JSON');load.onclick=guarded(async()=>{const input=raw.value,serial=d.serial,projectId=project.id;const result=await api('/api/v1/teams/validate',{method:'POST',body:{definition:parseJSON(input),name:d.name}}).catch(error=>{if(teamAuthor===d&&d.serial===serial)status.textContent=error.message;throw error;});if(teamAuthor!==d||d.serial!==serial||raw.value!==input||project?.id!==projectId)throw new Error('载入期间发生新编辑，当前草稿已保留。');d.definition=result.definition;d.raw='';d.buffers.clear();teamDraftChanged(d);renderTeamAuthor();});advanced.append(load);fields.append(advanced);
 teamField(fields,'导出绑定名',d.name,value=>{d.name=value;changed();});const source=window.ChaosCode.render(d.preview?.source||'',{language:'chaos',label:'团队源码'});source.classList.add('team-author-source');source.id='teamAuthorSource';dialog.append(source);
 const actions=element('div','team-author-actions'),validate=element('button','','验证并生成源码'),insert=element('button','primary','导入为团队模块草稿'),copy=element('button','','复制源码'),close=element('button','','关闭并保留草稿');insert.id='teamAuthorImport';insert.disabled=!d.preview;validate.onclick=guarded(async()=>{if(d.buffers.size||!Array.from(dialog.querySelectorAll('input,textarea,select')).every(input=>input.reportValidity()))throw new Error('请先修正输入格式。');const serial=d.serial,projectId=project.id,version=project.version,file=activeFile,edit=editSerial,definition=parseJSON(stringifyJSON(d.definition)),name=d.name;status.textContent='共享语言校验器验证中…';const result=await api('/api/v1/teams/validate',{method:'POST',body:{definition,name}}).catch(error=>{if(teamAuthor===d&&d.serial===serial)status.textContent=error.message;throw error;});if(teamAuthor!==d||d.serial!==serial||project?.id!==projectId)throw new Error('验证期间出现新编辑，当前草稿已保留。');d.preview={...result,serial,projectId,version,file,edit};window.ChaosCode.update(source,result.source,{language:'chaos',label:'团队源码'});insert.disabled=false;status.textContent='定义已验证 · '+result.definitionHash.slice(0,12)+' · 未执行角色';});
 insert.onclick=guarded(()=>{const p=d.preview;if(!p||p.serial!==d.serial||project?.id!==p.projectId||project.version!==p.version||activeFile!==p.file||editSerial!==p.edit)throw new Error('定义或源码工作区已变化；请重新验证，当前草稿仍保留。');window.ChaosIDE.importSourceModule(p.source,d.name,'teams');d.dirty=false;dialog.close();});copy.onclick=guarded(async()=>{if(!d.preview)throw new Error('请先验证生成源码。');await navigator.clipboard.writeText(d.preview.source);toast('已复制团队源码');});close.onclick=()=>dialog.close();actions.append(validate,copy,insert,close);dialog.append(actions);
}

async function saveLanguageDraft(){if(!syntaxDirty)return project;const ir=clone(programDraft),serial=editSerial,file=activeFile;const result=await api('/api/projects/'+project.id+'/program',{method:'POST',body:{version:project.version,program:ir,file}});if(serial===editSerial){setProject(result);await loadProgram();}else project.version=result.version;toast('程序结构和源码已同步保存');return project;}
$('#applyProgram').onclick=guarded(saveLanguageDraft);
$('#moduleSelect').onchange=guarded(async e=>{const next=e.target.value;if(dirty)await save();activeFile=next;onLanguageProject();});
$('#addModule').onclick=guarded(async()=>{if(dirty)await save();const name=prompt('模块文件名，例如 lib/math.chaos');if(!name)return;if(name in project.files)throw new Error('模块已存在');project.files[name]='// '+name+'\nexport {};\n';activeFile=name;markDirty('source');await save();});
$('#setEntry').onclick=guarded(async()=>{if(dirty)await save();project.entry=activeFile;project.source=project.files[activeFile];markDirty('source');await save();toast('程序入口已切换到 '+activeFile);});
$('#formatSource').onclick=guarded(async()=>{if(dirty)await save();const current=await api('/api/projects/'+project.id+'/program?file='+encodeURIComponent(activeFile));const response=await api('/api/projects/'+project.id+'/program',{method:'POST',body:{version:project.version,program:current.program,file:activeFile}});setProject(response);toast('已格式化（注释不保留）');});
$('#languageDemo').onclick=guarded(async()=>{if(dirty)await save();const file='language-demo.chaos';if(!(file in project.files))project.files[file]='import "std/option" as option;\n\nrec {\n  fn even(n: Int) -> Bool { if n == 0 { true } else { odd(n - 1) } }\n  fn odd(n: Int) -> Bool { if n == 0 { false } else { even(n - 1) } }\n}\nvar total: Int = 0;\nfor n in range(1, 6) { total = total + n; }\nlet answer = match option.Some(total) {\n  option.Some(value) if value > 0 => value,\n  option.None() => 0,\n  _ => 0\n};\nlet handled = try { 1 / 0 } catch error { error.code };\n{sum: answer, even: even(200), handled: handled}\n';activeFile=file;project.entry=file;project.source=project.files[file];markDirty('source');await save();toast('语言示例已作为入口；原入口文件仍保留在模块列表中');});

for(const [selector,id]of [['#sourceView .source-actions','teamAuthorButton'],['.structure-heading','teamStructureAuthorButton']]){const target=document.querySelector(selector);if(target){const button=element('button','','编写团队');button.id=id;button.onclick=guarded(openTeamAuthor);target.append(button);}}
window.addEventListener('beforeunload',event=>{if([...teamDrafts.values()].some(d=>d.dirty)){event.preventDefault();event.returnValue='';}});
